changeSet.rollback:
UPDATE theme
SET tokens = (tokens - 'border-tile' - 'tile-line') || $J${
  "bg-page": "#faf1eb",
  "pixel-corners": "polygon(0 8px, 4px 8px, 4px 4px, 8px 4px, 8px 0, calc(100% - 8px) 0, calc(100% - 8px) 4px, calc(100% - 4px) 4px, calc(100% - 4px) 8px, 100% 8px, 100% calc(100% - 8px), calc(100% - 4px) calc(100% - 8px), calc(100% - 4px) calc(100% - 4px), calc(100% - 8px) calc(100% - 4px), calc(100% - 8px) 100%, 8px 100%, 8px calc(100% - 4px), 4px calc(100% - 4px), 4px calc(100% - 8px), 0 calc(100% - 8px))",
  "drop-2": "drop-shadow(0 1px 1px rgba(33, 26, 22, 0.06)) drop-shadow(0 7px 11px rgba(33, 26, 22, 0.1))",
  "drop-3": "drop-shadow(0 2px 1px rgba(33, 26, 22, 0.08)) drop-shadow(0 12px 18px rgba(33, 26, 22, 0.14))",
  "drop-4": "drop-shadow(0 3px 2px rgba(33, 26, 22, 0.1)) drop-shadow(0 18px 26px rgba(33, 26, 22, 0.18))"
}$J$::jsonb
WHERE key = 'wave-01';
